import{_ as t,c as a,o,ag as r}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Bounded agent and tool workflows","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/workflows/index.md","filePath":"applied-ai/workflows/index.md"}'),n={name:"applied-ai/workflows/index.md"};function i(d,e,s,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="bounded-agent-and-tool-workflows" tabindex="-1">Bounded agent and tool workflows <a class="header-anchor" href="#bounded-agent-and-tool-workflows" aria-label="Permalink to “Bounded agent and tool workflows”">​</a></h1><p>A fixed workflow chooses steps in application code. An agent-directed workflow lets a model propose some next steps <strong>within application-owned limits</strong>. A graph, a chatbot or an n8n canvas can implement either; the tool names or framework do not determine autonomy.</p><h2 id="reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to “Reading order”">​</a></h2><ol><li><a href="./../../python-for-ai/tool-boundaries.html">Typed tool boundary</a>: exact allowlist, bounded complete arguments/results, authenticated current resource checks and call/result identity.</li><li><a href="./../../python-for-ai/history-and-workflows.html">History/checkpoints</a>: lossy summaries remain data; persist checked artifact references rather than promises.</li><li><a href="./../../python-for-ai/tool-workflow-state.html">State and budgets</a>: validated finite routes, local SQLite revisions and resource counters.</li><li><a href="./../../python-for-ai/approved-writes.html">Approved writes</a>: command-bound trusted approval and local atomic effect/receipt.</li><li><a href="./resumable-runs.html">Resumable runs</a>: connect state, artifacts, approval, recovery, deadlines and reservations.</li><li><a href="./../../python-for-ai/workflow-diagnostics.html">Diagnostics</a>, <a href="./../../python-for-ai/provenance-and-oversight.html">oversight/audit</a>, <a href="./../../python-for-ai/evaluation-lab.html">evaluation</a>: attempted steps, committed effects and supported task results are different evidence.</li><li>Optional <a href="./../../python-for-ai/graph-memory.html">LangGraph</a> and <a href="./../../python-for-ai/mcp-primitives.html">MCP</a>: framework/protocol adapters after the plain owner works.</li></ol><h2 id="fixed-versus-model-directed-execution" tabindex="-1">Fixed versus model-directed execution <a class="header-anchor" href="#fixed-versus-model-directed-execution" aria-label="Permalink to “Fixed versus model-directed execution”">​</a></h2><table tabindex="0"><thead><tr><th>Task shape</th><th>Suitable baseline</th><th>Additional responsibility if model-directed</th></tr></thead><tbody><tr><td>Lookup → answer → validate</td><td>Fixed sequence</td><td>Usually no missing routing need</td></tr><tr><td>Choose one of several bounded searches</td><td>Validated enum proposal</td><td>Name/argument/scope checks; charge every attempted branch</td></tr><tr><td>Rename a note</td><td>Proposal → trusted human approval → exact executor</td><td>Model cannot approve its own proposal or change it after approval</td></tr><tr><td>Unknown open-ended investigation</td><td>Bounded iterative policy, if justified</td><td>Stop conditions, repeated-call detection, aggregate costs, recovery and a stronger evaluation suite</td></tr></tbody></table><p>For a bounded routing example the permitted proposal is <code>lookup_note(source_id)</code> or <code>finish(answer_draft)</code>. The application validates the complete proposal, derives identity/scope independently and reserves a call before dispatch. Unknown names, extra owner fields, repeated calls beyond the cap and malformed outputs stop without a fallback shell/URL tool. <code>finish</code> still needs the normal evidence/answer checks; it cannot assert <code>checked=true</code>.</p><p>This is the contract for an optional model-directed branch, not a claim the existing graph runs an autonomous model. The current executable graph is START→lookup→END with RAM snapshots. Its value is demonstrating scoped tool composition, not crash durability or model reasoning.</p><h2 id="keep-every-transition-observable-and-bounded" tabindex="-1">Keep every transition observable and bounded <a class="header-anchor" href="#keep-every-transition-observable-and-bounded" aria-label="Permalink to “Keep every transition observable and bounded”">​</a></h2><p>Bound steps/fan-out/attempts, input/result bytes, model context/output, per-call and overall time, queue/admission and money separately. One owner accounts retries, fallback, counting, grading and resumed work. Persist remaining limits; a restart, forgotten graph thread or expired lease must not grant a fresh allocation.</p><p>Tool output, retrieved text and summaries can contain instructions, fake approvals or exfiltration URLs. Keep them in data fields, use task-limited current permissions and never promote them into trusted routing/configuration. Safe projections/traces reduce collection; they do not detect every secret or prove semantic truth.</p><p><a href="./../../practice/applied-ai/resumable-workflow.html">Practice: staged P-335</a> · <a href="./../../workbench/applied-ai/python/">Runnable components</a></p>',12)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
